pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }
    function testRegression_property() public {
        c.assertionDisputedCallback(bytes32(uint256(1)));
        BaseEscalationManager.AssertionPolicy memory policy = c.getAssertionPolicy(bytes32(uint256(1)));
        assertTrue(policy.validateDisputers == false, "validateDisputers should be false in reference");
    }
}
